changeSet.sql:
CREATE OR REPLACE TRIGGER trg_incidencia_ciclo_vida
BEFORE INSERT OR UPDATE ON incidencia
FOR EACH ROW
DECLARE
    -- Centinela para comparar marcas que pueden ser NULL: convierte el NULL en un valor
    -- comparable, de modo que "poner a NULL una marca sellada" cuenta como modificacion.
    c_centinela CONSTANT TIMESTAMP(6) := TIMESTAMP '0001-01-01 00:00:00';
    -- Instante UNICO contra el que se valida la fila entera (coherencia dentro de la misma fila).
    l_ahora     TIMESTAMP(6) := SYS_EXTRACT_UTC(SYSTIMESTAMP);
BEGIN
    -- (1) Marcas selladas: una vez escritas no admiten modificacion ni borrado.
    IF UPDATING THEN
        IF :OLD.in_progress_at IS NOT NULL
           AND NVL(:NEW.in_progress_at, c_centinela) <> NVL(:OLD.in_progress_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20050, 'La marca de inicio de atención ya está sellada y no admite modificación');
        END IF;

        IF :OLD.resolved_at IS NOT NULL
           AND NVL(:NEW.resolved_at, c_centinela) <> NVL(:OLD.resolved_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20051, 'La marca de resolución ya está sellada y no admite modificación');
        END IF;

        IF :OLD.assigned_at IS NOT NULL
           AND NVL(:NEW.assigned_at, c_centinela) <> NVL(:OLD.assigned_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20052, 'La marca de asignación ya está sellada y no admite modificación');
        END IF;
    END IF;

    -- (2) Red de seguridad de AC-ASG-01: si la sentencia deja tecnico asignado sin marca de
    --     asignacion, la sella el motor con el instante del servidor. Solo actua con la marca
    --     vacia; una marca ya sellada la protege el bloque (1), que rechaza reescribirla.
    IF :NEW.assigned_technician_id IS NOT NULL AND :NEW.assigned_at IS NULL THEN
        :NEW.assigned_at := l_ahora;
    END IF;

    -- (3) Ninguna marca temporal del ciclo de vida puede ser futura.
    IF (:NEW.created_at        IS NOT NULL AND :NEW.created_at        > l_ahora)
    OR (:NEW.in_progress_at    IS NOT NULL AND :NEW.in_progress_at    > l_ahora)
    OR (:NEW.resolved_at       IS NOT NULL AND :NEW.resolved_at       > l_ahora)
    OR (:NEW.closed_at         IS NOT NULL AND :NEW.closed_at         > l_ahora)
    OR (:NEW.status_changed_at IS NOT NULL AND :NEW.status_changed_at > l_ahora)
    OR (:NEW.assigned_at       IS NOT NULL AND :NEW.assigned_at       > l_ahora)
    OR (:NEW.released_at       IS NOT NULL AND :NEW.released_at       > l_ahora) THEN
        RAISE_APPLICATION_ERROR(-20053, 'Una marca temporal del ciclo de vida no puede ser futura');
    END IF;

    -- (4) Comentario de resolucion: obligatorio al cerrar y prohibido fuera del cierre.
    --     REGEXP_INSTR recorre el CLOB completo sin truncarlo y devuelve 0 si no hay
    --     ningun caracter distinto de espacio (equivalente al "no vacio tras TRIM").
    IF :NEW.status = 'CERRADA' THEN
        IF :NEW.resolution_comment IS NULL
           OR DBMS_LOB.GETLENGTH(:NEW.resolution_comment) = 0
           OR NVL(REGEXP_INSTR(:NEW.resolution_comment, '[^[:space:]]'), 0) = 0 THEN
            RAISE_APPLICATION_ERROR(-20054, 'Debe indicar un comentario de resolución para cerrar la incidencia');
        END IF;
    ELSIF :NEW.resolution_comment IS NOT NULL THEN
        RAISE_APPLICATION_ERROR(-20055, 'El comentario de resolución solo existe en una incidencia cerrada');
    END IF;

    -- (5) Concurrencia optimista: version la lleva el motor, nunca la sentencia.
    --     Va al final para no incrementarla en escrituras que las reglas anteriores rechazan.
    IF UPDATING THEN
        :NEW.version := NVL(:OLD.version, 0) + 1;
    END IF;
END;

DECLARE
    v_admin       NUMBER;
    v_empleado    NUMBER;
    v_tec_a       NUMBER;
    v_tec_b       NUMBER;
    v_office      NUMBER;
    v_room        NUMBER;
    v_cat         NUMBER;
    v_inc         NUMBER;
    v_ultima      NUMBER;
    v_filas_a     NUMBER;
    v_filas_b     NUMBER;
    v_ganadores   NUMBER := 0;
    v_codigo      NUMBER;
    v_tecnico     incidencia.assigned_technician_id%TYPE;
    v_asignado_en incidencia.assigned_at%TYPE;
    v_status      incidencia.status%TYPE;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');

        -- La categoria tiene que estar ACTIVA aunque la fila ya existiese: el trigger
        -- trg_incidencia_clasificacion rechaza el alta sobre catalogo inactivo (REQ-100).
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_code = p_code;
    END sembrar_categoria;

    -- SEGUNDA CONEXION sobre la incidencia ganadora. La transaccion autonoma es independiente
    -- de la principal: ni ve sus cambios sin confirmar ni comparte sus bloqueos. Devuelve el
    -- SQLCODE obtenido (0 si pudo tomar la fila, que es justo lo que no debe ocurrir) y hace
    -- ROLLBACK SIEMPRE antes de salir, porque una transaccion autonoma que termina sin cerrarse
    -- (sin confirmar ni deshacer) provoca ORA-06519. Aqui solo se deshace: nada se confirma.
    FUNCTION tomar_en_otra_transaccion(p_inc NUMBER) RETURN NUMBER IS
        PRAGMA AUTONOMOUS_TRANSACTION;
        l_tecnico NUMBER;
        l_codigo  NUMBER;
    BEGIN
        SELECT assigned_technician_id
          INTO l_tecnico
          FROM incidencia
         WHERE incident_id = p_inc
           FOR UPDATE NOWAIT;
        l_codigo := 0;
        ROLLBACK;
        RETURN l_codigo;
    EXCEPTION
        WHEN OTHERS THEN
            l_codigo := SQLCODE;
            ROLLBACK;
            RETURN l_codigo;
    END tomar_en_otra_transaccion;

BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 902);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('MOBILIARIO', 'Mobiliario oraculo concurrencia', 901);

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'MOBILIARIO';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA54A' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA54A', 'Oficina Oraculo Concurrencia', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA54A';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    -- username, password_hash y password_algorithm son NOT NULL desde 06-usuario-credenciales.xml.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES ('Oraculo Concurrencia Admin', 'oraculo.tsk054.conc.admin@example.invalid',
                 'oraculo.tsk054.conc.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk054-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Empleado', 'oraculo.tsk054.conc.empleado@example.invalid',
                 'oraculo.tsk054.conc.empleado', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk054-empleado', 'argon2id', v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Tecnico A', 'oraculo.tsk054.conc.tecnico.a@example.invalid',
                 'oraculo.tsk054.conc.tecnico.a', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-tecnico-a', 'argon2id', v_admin)
      RETURNING user_id INTO v_tec_a;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Tecnico B', 'oraculo.tsk054.conc.tecnico.b@example.invalid',
                 'oraculo.tsk054.conc.tecnico.b', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-tecnico-b', 'argon2id', v_admin)
      RETURNING user_id INTO v_tec_b;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA54A' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA54A', 'Sala Oraculo Concurrencia', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA54A';

    -- 100 tomas en disputa de 100 incidencias distintas: en cada una, dos tecnicos emiten la
    -- MISMA sentencia condicional de REQ-153 y solo uno puede ganar.
    FOR i IN 1 .. 100 LOOP
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9054-' || LPAD(i, 6, '0'), v_room, v_cat,
                     'Toma concurrente numero ' || i || ' del oraculo de asignacion de incidencias',
                     v_empleado)
          RETURNING incident_id INTO v_inc;

        -- Conexion 1 (tecnico A): sentencia canonica de autoasignacion de AC-ASG-02.
        UPDATE incidencia
           SET assigned_technician_id = v_tec_a
         WHERE incident_id = v_inc
           AND assigned_technician_id IS NULL;
        v_filas_a := SQL%ROWCOUNT;

        -- Conexion 2 (tecnico B): exactamente la misma sentencia sobre la misma incidencia.
        UPDATE incidencia
           SET assigned_technician_id = v_tec_b
         WHERE incident_id = v_inc
           AND assigned_technician_id IS NULL;
        v_filas_b := SQL%ROWCOUNT;

        IF v_filas_a <> 1 THEN
            RAISE_APPLICATION_ERROR(-20940, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': la primera toma afecto a ' || v_filas_a || ' filas en lugar de 1');
        END IF;

        IF v_filas_b <> 0 THEN
            RAISE_APPLICATION_ERROR(-20941, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': la segunda toma afecto a ' || v_filas_b ||
                ' filas en lugar de 0: la incidencia admite doble asignacion');
        END IF;

        SELECT assigned_technician_id, assigned_at, status
          INTO v_tecnico, v_asignado_en, v_status
          FROM incidencia
         WHERE incident_id = v_inc;

        IF v_tecnico IS NULL OR v_tecnico <> v_tec_a OR v_tecnico = v_tec_b THEN
            RAISE_APPLICATION_ERROR(-20942, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': el responsable de la incidencia es ' || NVL(TO_CHAR(v_tecnico), 'NULL') ||
                ' y deberia ser el tecnico ganador ' || v_tec_a);
        END IF;

        IF v_asignado_en IS NULL THEN
            RAISE_APPLICATION_ERROR(-20943, 'ORACULO AC-ASG-01 iteracion ' || i ||
                ': la toma no ha sellado assigned_at con el instante del servidor');
        END IF;

        IF v_status <> 'ABIERTA' THEN
            RAISE_APPLICATION_ERROR(-20944, 'ORACULO REQ-153 RN-06 iteracion ' || i ||
                ': la asignacion ha cambiado el estado a ' || v_status || ' en lugar de dejarlo en ABIERTA');
        END IF;

        v_ganadores := v_ganadores + 1;
        v_ultima := v_inc;
    END LOOP;

    IF v_ganadores <> 100 THEN
        RAISE_APPLICATION_ERROR(-20945, 'ORACULO AC-ASG-02: se han contado ' || v_ganadores ||
            ' tomas ganadoras en lugar de 100');
    END IF;

    -- Bloqueo de fila entre transacciones DISTINTAS: la ultima incidencia, tomada por el tecnico A
    -- y todavia SIN CONFIRMAR, es intocable desde otra transaccion. ORA-01403 (100) porque la fila
    -- sin confirmar no existe para ella; ORA-00054 (-54) si llegase a verla y no pudiese bloquearla.
    -- Lo que NUNCA puede devolver es 0, que significaria que otra transaccion la ha arrebatado.
    v_codigo := tomar_en_otra_transaccion(v_ultima);
    IF v_codigo NOT IN (-54, 100) THEN
        RAISE_APPLICATION_ERROR(-20946, 'ORACULO AC-ASG-02: una transaccion ajena obtuvo ' || v_codigo ||
            ' sobre la incidencia tomada y sin confirmar; mientras la ganadora no confirma ninguna' ||
            ' transaccion ajena puede arrebatar la fila, solo cabe ORA-01403 (100) u ORA-00054 (-54)');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
